from collections import deque

def quickestWayUp(ladders, snakes):
    board = {start: end for start, end in ladders + snakes}
    queue = deque([(1, 0)])
    visited = set()

    while queue:
        position, rolls = queue.popleft()
        if position == 100:
            return rolls
        for i in range(1, 7):
            next_position = position + i
            if next_position > 100 or next_position in visited:
                continue
            visited.add(next_position)
            if next_position in board:
                queue.append((board[next_position], rolls + 1))
            else:
                queue.append((next_position, rolls + 1))
    return -1

